  "// Type imposé au MPD : {0}": "// Type overridden in the physical model: {0}",
  "// Attention : {0} n'a pas d'identifiant dans le MCD.": "// Warning: {0} has no identifier in the MCD.",
  "    // {0} n'a pas d'identifiant dans le MCD.": "    // {0} has no identifier in the MCD.",
  "    // Attention : {0} n'a pas d'identifiant dans le MCD.": "    // Warning: {0} has no identifier in the MCD.",
  "Nom de famille": "Last name",
